<?php require_once __DIR__.'/includes/config.php';
if (!empty($_SESSION['user_id'])) redirect('dashboard.php');
$errors=[];
if ($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf(); $business=trim($_POST['business_name']??''); $name=trim($_POST['full_name']??''); $email=strtolower(trim($_POST['email']??'')); $password=$_POST['password']??'';
 if(mb_strlen($business)<2||mb_strlen($business)>150)$errors[]='Enter a business name between 2 and 150 characters.';
 if(mb_strlen($name)<2||mb_strlen($name)>120)$errors[]='Enter your full name.';
 if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($email)>190)$errors[]='Enter a valid email address.';
 if(strlen($password)<10)$errors[]='Password must contain at least 10 characters.';
 if(!$errors){try{$stmt=$pdo->prepare('INSERT INTO users (business_name,full_name,email,password_hash) VALUES (?,?,?,?)');$stmt->execute([$business,$name,$email,password_hash($password,PASSWORD_DEFAULT)]);session_regenerate_id(true);$_SESSION['user_id']=(int)$pdo->lastInsertId();$_SESSION['actor_id']=$_SESSION['user_id'];$_SESSION['account_type']='owner';$_SESSION['full_name']=$name;$_SESSION['business_name']=$business;$_SESSION['csrf']=bin2hex(random_bytes(32));flash('Your Kasuwalink account is ready. Add your first product to get started.');redirect('dashboard.php');}catch(PDOException $ex){if($ex->getCode()==='23000')$errors[]='That email is already registered. Please log in.';else throw $ex;}}
}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Create account · Kasuwalink</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="assets/style.css" rel="stylesheet"></head><body><div class="auth-wrap"><div class="card auth-card"><a class="navbar-brand fw-bold mb-4" href="index.php"><span class="brand-mark">K</span> Kasuwalink</a><h1 class="h3 fw-bold">Start managing your business</h1><p class="muted mb-4">Create your free shop account.</p><?php foreach($errors as $error):?><div class="alert alert-danger"><?=e($error)?></div><?php endforeach;?><form method="post" autocomplete="on"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="mb-3"><label class="form-label" for="business_name">Business name</label><input class="form-control" id="business_name" name="business_name" required maxlength="150" value="<?=e($_POST['business_name']??'')?>"></div><div class="mb-3"><label class="form-label" for="full_name">Your full name</label><input class="form-control" id="full_name" name="full_name" required maxlength="120" value="<?=e($_POST['full_name']??'')?>"></div><div class="mb-3"><label class="form-label" for="email">Email address</label><input class="form-control" id="email" type="email" name="email" required maxlength="190" value="<?=e($_POST['email']??'')?>"></div><div class="mb-4"><label class="form-label" for="password">Password</label><input class="form-control" id="password" type="password" name="password" minlength="10" required autocomplete="new-password"><div class="form-text">Use at least 10 characters.</div></div><button class="btn btn-primary w-100 py-2">Create account</button></form><p class="text-center mt-4 mb-0">Already registered? <a href="login.php">Log in</a></p></div></div></body></html>
